// Eingang prüfen (Stefan 18.10.2026): Aufruf von "TALENTS Web" (Hochladen, Vorschlag schon angelegt), vom Chat (Text oder Datei) oder aus der Mail-Einordnung (Anhang).
// Eingang (json): quelle (hochladen | chat | mail), nutzer, vorschlag (nur Oberfläche), talent_id oder talent (Name), text (Chat), absender und mail_datum (Mail), datei_name;
// Datei im Binärfeld "datei" (oder data). Ergebnis: Felder für "Vorschlag anlegen".
const it = $input.first();
const e = it.json || {};
const s = v => String(v ?? '').trim();
const bin = it.binary || {};
const k = bin.datei ? 'datei' : (Object.keys(bin)[0] || '');
let groesse = 0, typ = '', name = s(e.datei_name);
if (k) {
  const buf = await this.helpers.getBinaryDataBuffer(0, k);
  groesse = buf.length;
  typ = String(bin[k].mimeType || '').toLowerCase().split(';')[0].trim();
  name = name || s(bin[k].fileName);
  const ende = (name.split('.').pop() || '').toLowerCase();
  if (typ === 'image/jpg') typ = 'image/jpeg';
  if (!typ || typ === 'application/octet-stream' || typ === 'text/plain') typ = { csv: 'text/csv', txt: 'text/plain', json: 'application/json', pdf: 'application/pdf', png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', webp: 'image/webp' }[ende] || typ;
}
const text = s(e.text).slice(0, 30000);
const vorhanden = !!(e.vorschlag && typeof e.vorschlag === 'object' && e.vorschlag.ok === true);
const anlage = { quelle: ['hochladen', 'chat', 'mail'].includes(s(e.quelle)) ? s(e.quelle) : 'chat', talent_id: s(e.talent_id), talent: s(e.talent),
  absender: s(e.absender), mail_datum: s(e.mail_datum), datei_name: name.slice(0, 120),
  datei_typ: k ? typ : (text ? 'text/plain' : ''), datei_groesse: String(k ? groesse : Buffer.byteLength(text, 'utf8')) };
return [{ json: { vorhanden, nutzer: s(e.nutzer), anlage: JSON.stringify(anlage), binaer: k, text } }];

// Vorschlag prüfen (Stefan 18.10.2026): Vorschlag aus der Oberfläche oder frisch angelegt; Datei für Ablage und KI wieder anhängen
const E = $('Eingang prüfen').first().json;
const S = $('Start').first();
const v = E.vorhanden ? S.json.vorschlag : ($input.first().json.r || {});
if (!v || v.ok !== true) return [{ json: { ok: false, fehler: String((v && v.fehler) || 'Der Vorschlag konnte nicht angelegt werden.'), grund: v && v.grund, kandidaten: v && v.kandidaten } }];
const out = { json: Object.assign({}, v, { nutzer: E.nutzer, hat_datei: !!E.binaer }) };
if (E.binaer) out.binary = { datei: S.binary[E.binaer] };
return [out];

// Ablageauftrag (Stefan 18.10.2026): Originaldatei als Beleg der Quelle im Ordner des Talents (Zahlen-Eingang) ablegen
const it = $input.first();
return [{ json: { aktion: 'ablegen', bereich: 'ally', pfad: it.json.datei_pfad, ueberschreiben: false }, binary: { datei: it.binary.datei } }];

// KI vorbereiten (Stefan 18.10.2026): Auftrag zum Auslesen. Die KI liest nur ab, was im Dokument steht; gespeichert wird erst nach Bestätigung durch den Manager.
// Instagram-Kanal (Broadcast Channel) als eigener Bereich "kanal" (Stefan 19.10.2026, Migration 55): Kennzahlen aus der Datenbank (kontext.kennzahlen),
// nur Plattform instagram, getrennt vom Konto. Das BOM am Textanfang wird ohne Unicode-Escape im Quelltext entfernt (die Werkzeug-Schicht wandelt solche Escapes um).
const V = $('Vorschlag prüfen').first();
const v = V.json;
const E = $('Eingang prüfen').first().json;
const K = v.kontext || {};
const ki = v.ki || {};
let ablage = '';
try { const a = $('Datei ablegen (SPEICHER 1)').first().json; if (a && a.ok !== true) ablage = 'Die Originaldatei konnte nicht im Speicherort abgelegt werden.'; } catch (e) { ablage = ''; }
const kz = (Array.isArray(K.kennzahlen) ? K.kennzahlen : []).reduce((m, x) => { (m[x.bereich] = m[x.bereich] || []).push(x.kennzahl); return m; }, {});
const auftrag = 'Lies Statistik-Zahlen eines Social-Media-Kontos oder eines Instagram-Kanals (Broadcast Channel) aus dem Dokument (Screenshot, PDF oder Export einer Plattform).\n'
  + 'Talent: ' + (v.anzeigename || '') + '. Bekannte Plattformen: ' + ((K.plattformen || []).join(', ') || 'keine') + '. Bekannte Konten: ' + ((K.konten || []).join(', ') || 'keine') + '.\n'
  + 'Gib NUR ein JSON-Objekt zurück, ohne weiteren Text:\n'
  + '{"plattform": "instagram|tiktok|youtube|facebook|threads|pinterest", "konto": "@name oder leer", "werte": [{"bereich": "konto|beitrag|zielgruppe|kanal", "kennzahl": "…", "wert": 123, '
  + '"von": "JJJJ-MM-TT", "bis": "JJJJ-MM-TT", "stand": "JJJJ-MM-TT", "werte": {"Schlüssel": 12.5}, "beitrag_datum": "JJJJ-MM-TT", "beitrag_link": "https://…", "beitrag_art": "Reel|Karussell|Bild|Video|Story"}], "hinweise": ["…"]}\n'
  + 'Erlaubte Kennzahlen: konto: ' + (kz.konto || []).join(', ') + ' (follower mit "stand"); beitrag: ' + (kz.beitrag || []).join(', ') + ' (je Beitrag, mit "stand"); '
  + 'zielgruppe: ' + (kz.zielgruppe || []).join(', ') + ' (Verteilung in "werte", z. B. {"18-24": 31.5}; Geschlecht mit F, M, U).\n'
  + (kz.kanal ? 'kanal: ' + kz.kanal.join(', ') + ' (nur für die Statistik eines Instagram-Kanals/Broadcast Channel, dann "plattform": "instagram"; Gesamtinteraktionen = interaktionen, Teilen = geteilt, '
    + 'Umfrage-Stimmen = umfrage_stimmen; mitglieder nur, wenn die Mitgliederzahl sichtbar ist, mit "stand"). Kanal-Zahlen nie als konto eintragen.\n' : '')
  + 'Regeln: Übernimm nur Zahlen, die eindeutig im Dokument stehen. Nichts schätzen, nichts ausrechnen, nichts ergänzen. Zahlen ohne Tausenderpunkte, Prozentwerte ohne %-Zeichen. '
  + 'Datumsangaben nur, wenn sie im Dokument stehen; steht dort nur "letzte 30 Tage" o. Ä. ohne Datum, lass von und bis weg und schreibe das in "hinweise". '
  + 'Unklares oder nicht Zuordenbares nur in "hinweise" (höchstens 5, kurz).';
let weg = v.art === 'bild' ? 'bild' : v.art === 'pdf' ? 'pdf' : 'text';
if (ki.gesperrt) weg = 'gesperrt';
let inhalt = '';
if (weg === 'text') {
  if (E.text) inhalt = E.text;
  else if (V.binary && V.binary.datei) { const buf = await this.helpers.getBinaryDataBuffer(0, 'datei'); inhalt = buf.toString('utf8').replace(new RegExp('^' + String.fromCharCode(0xFEFF)), ''); }
  inhalt = inhalt.slice(0, 30000);
  if (!inhalt.trim()) weg = 'leer';
}
const out = { json: { weg, modell: ki.modell || '', system: auftrag, text: weg === 'text' ? 'DOKUMENT:\n' + inhalt : auftrag, sperre_text: ki.sperre_text || '', ablage_hinweis: ablage, vorschlag_id: v.vorschlag_id, nutzer: v.nutzer } };
if ((weg === 'bild' || weg === 'pdf') && V.binary && V.binary.datei) out.binary = { datei: V.binary.datei };
if ((weg === 'bild' || weg === 'pdf') && !out.binary) out.json.weg = 'leer';
return [out];

// Ergebnis (Stefan 18.10.2026): Text für Chat bzw. Mail-Einordnung (setzt die Datenbank)
let r = {};
try { r = $('Ergebnis speichern').first().json.r || {}; } catch (e) { r = {}; }
if (!r.vorschlag_id) {
  const v = $('Vorschlag prüfen').first().json;
  return [{ json: { ok: false, text: String(v.fehler || 'Nicht ausgelesen.'), grund: v.grund || null, kandidaten: v.kandidaten || null } }];
}
return [{ json: { ok: r.ok === true && r.fehlgeschlagen !== true, text: String(r.text || r.fehler || ''), vorschlag_id: r.vorschlag_id, talent_id: r.talent_id, anzahl: r.anzahl || 0 } }];

// Antwort lesen (Stefan 18.10.2026): JSON aus der KI-Antwort; ohne lesbare Antwort ein Fehler (Vorschlag "nicht ausgelesen", Werte von Hand möglich)
const K = $('KI vorbereiten').first().json;
let d;
if (K.weg === 'gesperrt') d = { fehler: K.sperre_text || 'Das KI-Budget für diesen Monat ist erreicht.' };
else if (K.weg === 'leer') d = { fehler: 'Die Datei ist leer oder nicht lesbar.' };
else {
  const c = $input.first().json.content;
  const roh = (Array.isArray(c) ? c : []).filter(b => b && b.type === 'text').map(b => String(b.text || '')).join('\n');
  const a = roh.indexOf('{'), z = roh.lastIndexOf('}');
  try { d = JSON.parse(roh.slice(a, z + 1)); } catch (e) { d = null; }
  if (!d || typeof d !== 'object' || Array.isArray(d)) d = { fehler: 'Die KI hat keine lesbare Antwort geliefert.' };
}
if (K.ablage_hinweis && !d.fehler) d.hinweise = (Array.isArray(d.hinweise) ? d.hinweise : []).concat([K.ablage_hinweis]);
return [{ json: { vorschlag_id: K.vorschlag_id, daten: JSON.stringify(d) } }];
